const $=s=>document.querySelector(s);
const STORE='dkd_v4_data', SESSION='dkd_v4_session';
const LOGO='data:image/jpeg;base64,'+``;
const defaults={
 users:[
  {u:'gaojiancheng',p:'123456',role:'boss',name:'老板'},
  {u:'beijing',p:'bj123456',role:'beijing',name:'北京店'},
  {u:'hangzhou',p:'hz123456',role:'hangzhou',name:'杭州店'}
 ],tables:[],orders:[],plans:[],settings:{sound:true,packages:[60,90,120,180],prices:{60:39,90:59,120:79,180:99}}
};
let data=load(),session=JSON.parse(localStorage.getItem(SESSION)||'null'),view='home',selectedStore='beijing',timer,audioReady=false,alarmTimer=null;
function clone(x){return JSON.parse(JSON.stringify(x))}
function load(){try{let d=JSON.parse(localStorage.getItem(STORE)||'null');return d?Object.assign(clone(defaults),d):clone(defaults)}catch{return clone(defaults)}}
function save(){localStorage.setItem(STORE,JSON.stringify(data))}
function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now()+'_'+Math.random()}
function currentStore(){return session?.role==='boss'?selectedStore:session?.role}
function storeName(s){return s==='beijing'?'北京店':'杭州店'}
function fmt(ms){let over=ms<0;ms=Math.abs(ms);let s=Math.floor(ms/1000),h=Math.floor(s/3600),m=Math.floor(s%3600/60),sec=s%60;return `${over?'超时 ':''}${h?String(h).padStart(2,'0')+':':''}${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`}
function login(u,p){let x=data.users.find(v=>v.u===u&&v.p===p);if(!x)return alert('账号或密码错误');session={u:x.u,role:x.role,name:x.name};localStorage.setItem(SESSION,JSON.stringify(session));selectedStore=x.role==='boss'?'beijing':x.role;render()}
function logout(){localStorage.removeItem(SESSION);session=null;render()}
function changePassword(form){let me=data.users.find(x=>x.u===session.u);if(form.old.value!==me.p)return alert('原密码不正确');if(form.n1.value.length<6)return alert('新密码至少6位');if(form.n1.value!==form.n2.value)return alert('两次新密码不一致');me.p=form.n1.value;save();form.reset();alert('密码修改成功')}
function tables(){return data.tables.filter(x=>x.store===currentStore())}
function orders(){return data.orders.filter(x=>x.store===currentStore())}
function plans(){return data.plans.filter(x=>x.store===currentStore())}
function startTable(f){let mins=+f.duration.value;data.tables.push({id:uid(),store:currentStore(),no:f.no.value.trim(),people:+f.people.value||1,duration:mins,startAt:Date.now(),endAt:Date.now()+mins*60000,paused:false,remark:f.remark.value.trim(),alerts:[]});save();closeModal();render()}
function pauseTable(id){let t=data.tables.find(x=>x.id===id);if(!t.paused){t.paused=true;t.pauseAt=Date.now()}else{t.endAt+=Date.now()-t.pauseAt;t.paused=false;delete t.pauseAt}save();render()}
function extendTable(id,m){let t=data.tables.find(x=>x.id===id);t.endAt+=m*60000;t.alerts=[];save();render()}
function checkout(id){let t=data.tables.find(x=>x.id===id),price=data.settings.prices[t.duration]||0,overtime=Math.max(0,Date.now()-t.endAt),amount=price+Math.ceil(overtime/1800000)*20;data.orders.unshift({...t,orderId:uid(),checkoutAt:Date.now(),amount,overtime,pay:'微信'});data.tables=data.tables.filter(x=>x.id!==id);save();render()}
function enableAudio(){audioReady=true;beep(1);alert('声音提醒已开启')}
function beep(n=1){if(!audioReady||!data.settings.sound)return;try{let c=new(window.AudioContext||window.webkitAudioContext)();for(let i=0;i<n;i++){let o=c.createOscillator(),g=c.createGain(),t=c.currentTime+i*.22;o.frequency.value=880;o.connect(g);g.connect(c.destination);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.25,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+.16);o.start(t);o.stop(t+.18)}}catch{}}
function tick(){let due=tables().some(t=>!t.paused&&Date.now()>=t.endAt);if(due&&!alarmTimer){beep(4);alarmTimer=setInterval(()=>beep(4),5000)}if(!due&&alarmTimer){clearInterval(alarmTimer);alarmTimer=null}tables().forEach(t=>{if(t.paused)return;let m=Math.ceil((t.endAt-Date.now())/60000);[10,5,1].forEach(a=>{if(m===a&&!t.alerts.includes(a)){t.alerts.push(a);beep(a===1?3:a===5?2:1);save()}})});if(session&&view==='home')render(false)}
function weekLabel(ts=Date.now()){let d=new Date(ts),day=(d.getDay()+6)%7;d.setHours(0,0,0,0);d.setDate(d.getDate()-day);let e=new Date(d);e.setDate(e.getDate()+6);return `${d.getMonth()+1}.${d.getDate()}-${e.getMonth()+1}.${e.getDate()}`}
function addPlan(f){data.plans.unshift({id:uid(),store:currentStore(),week:weekLabel(),color:f.color.value.trim(),qty:+f.qty.value||1,unit:f.unit.value,status:'未采购',remark:f.remark.value.trim(),createdAt:Date.now(),doneAt:null,favorite:false});save();closeModal();view='beads';render()}
function togglePlan(id){let p=data.plans.find(x=>x.id===id);p.status=p.status==='已采购'?'未采购':'已采购';p.doneAt=p.status==='已采购'?Date.now():null;save();render()}
function favoritePlan(id){let p=data.plans.find(x=>x.id===id);p.favorite=!p.favorite;save();render()}
function deletePlan(id){if(confirm('删除这条补豆计划？')){data.plans=data.plans.filter(x=>x.id!==id);save();render()}}
function copyPending(){let a=plans().filter(x=>x.status==='未采购');let txt=['豆可兜补豆采购单',`${storeName(currentStore())}｜${weekLabel()}`,'',...a.map(x=>`${x.color}  ${x.qty}${x.unit}${x.remark?'  '+x.remark:''}`)].join('\n');navigator.clipboard?.writeText(txt);alert(a.length?'未采购清单已复制，可直接发给厂家':'暂无未采购项目')}
function exportCsv(){let a=plans().filter(x=>x.status==='未采购');if(!a.length)return alert('暂无未采购项目');let csv='色号,数量,单位,备注\n'+a.map(x=>[x.color,x.qty,x.unit,x.remark].map(v=>`"${String(v||'').replaceAll('"','""')}"`).join(',')).join('\n');let b=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),u=URL.createObjectURL(b),el=document.createElement('a');el.href=u;el.download=`${storeName(currentStore())}-补豆采购单-${new Date().toISOString().slice(0,10)}.csv`;el.click();URL.revokeObjectURL(u)}
function render(reset=true){if(!session)return renderLogin();if(reset)scrollTo(0,0);let st=currentStore(),os=orders(),today=new Date().toDateString(),todayO=os.filter(x=>new Date(x.checkoutAt).toDateString()===today),rev=todayO.reduce((a,b)=>a+b.amount,0),people=tables().reduce((a,b)=>a+b.people,0)+todayO.reduce((a,b)=>a+b.people,0);$('#app').innerHTML=`<main class="page"><header class="top"><div class="brand-line"><img class="header-logo" src="${LOGO}"><div><div class="sub">${storeName(st)} · ${session.name}</div></div></div><button class="secondary" onclick="logout()">退出</button></header>${session.role==='boss'?`<div class="store-switch"><button class="${st==='beijing'?'active':''}" onclick="selectedStore='beijing';render()">北京店</button><button class="${st==='hangzhou'?'active':''}" onclick="selectedStore='hangzhou';render()">杭州店</button></div>`:''}${view==='home'?homeHtml(rev,people):view==='orders'?ordersHtml():view==='beads'?beadsHtml():settingsHtml()}<nav class="bottom"><button class="${view==='home'?'active':''}" onclick="view='home';render()">首页</button><button class="${view==='orders'?'active':''}" onclick="view='orders';render()">订单</button><button class="${view==='beads'?'active':''}" onclick="view='beads';render()">补豆</button><button class="${view==='settings'?'active':''}" onclick="view='settings';render()">设置</button></nav></main>`}
function homeHtml(revenue,people){let ts=tables();return `<section class="stats"><div class="stat"><span>营业额</span><b>¥${revenue}</b></div><div class="stat"><span>营业中</span><b>${ts.length}</b></div><div class="stat"><span>人数</span><b>${people}</b></div></section><div class="actions"><button onclick="showTableModal()">＋ 开台</button><button class="secondary" onclick="enableAudio()">🔊 开启声音</button></div>${ts.length?`<section class="cards">${ts.map(tableCard).join('')}</section>`:`<section class="empty"><b>暂无营业桌</b><span>当前没有正在进行的营业桌</span><button onclick="showTableModal()">立即开台</button></section>`}`}
function tableCard(t){let left=t.paused?t.endAt-t.pauseAt:t.endAt-Date.now(),cls=left<=0?'danger':left<=600000?'warn':'';return `<article class="table-card ${cls}"><div class="card-head"><b>${t.no}</b><span class="pill ${left<=0?'red':left<=600000?'yellow':'green'}">${left<=0?'已超时':left<=600000?'快到期':'正常'}</span></div><div class="countdown">${fmt(left)}</div><div class="meta"><span>${t.people}人</span><span>${t.duration}分钟</span><span>${t.remark||'无备注'}</span></div><div class="btn-row"><button class="secondary" onclick="extendTable('${t.id}',30)">+30</button><button class="secondary" onclick="pauseTable('${t.id}')">${t.paused?'继续':'暂停'}</button><button onclick="checkout('${t.id}')">结账</button></div></article>`}
function ordersHtml(){let a=orders();return `<section class="section-head"><h2>订单记录</h2></section>${a.length?a.map(o=>`<article class="list-card"><b>${o.no}</b><strong>¥${o.amount}</strong><small>${o.people}人 · ${o.duration}分钟 · ${new Date(o.checkoutAt).toLocaleString()}</small></article>`).join(''):`<section class="empty"><b>暂无订单</b><span>完成结账后会自动保存在这里</span></section>`}`}
function beadsHtml(){let a=plans(),todo=a.filter(x=>x.status==='未采购'),done=a.filter(x=>x.status==='已采购'),month=new Date().getMonth(),monthDone=a.filter(x=>x.status==='已采购'&&new Date(x.doneAt).getMonth()===month),qsum=monthDone.reduce((n,x)=>n+x.qty*(x.unit==='半斤'?0.5:1),0);return `<section class="section-head"><div><h2>补豆采购</h2><p>按周填写计划，只导出未采购项目</p></div><button onclick="showPlanModal()">＋ 添加</button></section><section class="stats"><div class="stat"><span>待采购</span><b>${todo.length}</b></div><div class="stat"><span>本月已采购</span><b>${monthDone.length}</b></div><div class="stat"><span>本月总量</span><b>${qsum}斤</b></div></section><div class="actions"><button class="secondary" onclick="copyPending()">复制清单</button><button class="secondary" onclick="exportCsv()">导出表格</button></div><div class="filters"><button class="active">全部 ${a.length}</button><button>待采购 ${todo.length}</button><button>已采购 ${done.length}</button></div>${a.length?a.sort((x,y)=>Number(y.favorite)-Number(x.favorite)||y.createdAt-x.createdAt).map(p=>`<article class="plan-card ${p.status==='已采购'?'done':''}"><div><div class="plan-title"><button class="star" onclick="favoritePlan('${p.id}')">${p.favorite?'★':'☆'}</button><b>${p.color}</b><span class="pill ${p.status==='已采购'?'green':'yellow'}">${p.status}</span></div><small>${p.week} · ${p.qty}${p.unit}${p.remark?' · '+p.remark:''}</small></div><div class="plan-actions"><button class="secondary" onclick="togglePlan('${p.id}')">${p.status==='已采购'?'改为未采':'标记已采购'}</button><button class="ghost" onclick="deletePlan('${p.id}')">删除</button></div></article>`).join(''):`<section class="empty"><b>还没有补豆计划</b><span>发现补充包快用完时，添加本周计划即可</span><button onclick="showPlanModal()">添加补豆计划</button></section>`}`}
function settingsHtml(){return `<section class="section-head"><h2>设置</h2></section><article class="settings-card"><h3>修改密码</h3><form onsubmit="event.preventDefault();changePassword(this)"><input name="old" type="password" placeholder="原密码" required><input name="n1" type="password" placeholder="新密码（至少6位）" required><input name="n2" type="password" placeholder="再次输入新密码" required><button>保存新密码</button></form></article><article class="settings-card"><h3>提醒说明</h3><p>倒计时按真实结束时间计算。切换应用或锁屏后回来，时间仍会自动校准；网页在前台时可响铃提醒。</p></article>`}
function renderLogin(){$('#app').innerHTML=`<div class="login"><section class="login-card"><img class="login-logo" src="${LOGO}"><h1>门店管理系统</h1><form onsubmit="event.preventDefault();login(this.u.value.trim(),this.p.value)"><input name="u" autocomplete="username" placeholder="请输入账号" required><input name="p" type="password" autocomplete="current-password" placeholder="请输入密码" required><button>登录</button></form></section></div>`}
function showTableModal(){$('#app').insertAdjacentHTML('beforeend',`<div class="modal" onclick="if(event.target===this)closeModal()"><form class="sheet" onsubmit="event.preventDefault();startTable(this)"><h2>开台</h2><input name="no" placeholder="桌号" required><input name="people" type="number" min="1" value="1"><select name="duration">${data.settings.packages.map(x=>`<option value="${x}">${x}分钟</option>`).join('')}</select><input name="remark" placeholder="备注（选填）"><div class="actions"><button type="button" class="secondary" onclick="closeModal()">取消</button><button>开始倒计时</button></div></form></div>`)}
function showPlanModal(){$('#app').insertAdjacentHTML('beforeend',`<div class="modal" onclick="if(event.target===this)closeModal()"><form class="sheet" onsubmit="event.preventDefault();addPlan(this)"><h2>添加补豆计划</h2><input name="color" placeholder="MARD色号，如 01 / 198" required><input name="qty" type="number" min="0.5" step="0.5" value="1" required><select name="unit"><option value="半斤">半斤</option><option value="一斤">一斤</option></select><input name="remark" placeholder="备注（选填）"><div class="actions"><button type="button" class="secondary" onclick="closeModal()">取消</button><button>加入待采购</button></div></form></div>`)}
function closeModal(){document.querySelector('.modal')?.remove()}
addEventListener('load',()=>{if(session?.role==='boss')selectedStore='beijing';render();clearInterval(timer);timer=setInterval(tick,1000)});
